};
const riskFromAnswer = a => (String(a || '').match(/^(Low|Medium|High)\b/) || [])[1] || null;
const slug = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
// ---- end shared helpers ----


// Current allocation + the RISK PLAN. The plan is decided here, in code, so the agents follow one
// consistent rulebook: what the user said they can stomach, capped by what their goal date and
// safety net can actually afford.
const d = $('Restore User State').first().json;
const holdings = d.savings_investments || [];
const age = d.profile?.age || 30;
const cur = d.profile?.currency || 'INR';

const classify = (type) => {
  const t = String(type || '').toLowerCase();
  if (['gold', 'sgb', 'silver'].some(k => t.includes(k))) return 'gold';
  if (['etf', 'stock', 'equity', 'mutual fund', 'mf', 'index', 'nps', 'elss'].some(k => t.includes(k))) return 'equity';
  if (['fd', 'fixed deposit', 'bond', 'ppf', 'epf', 'debt', 'rd', 'recurring'].some(k => t.includes(k))) return 'debt';
  return 'cash';
};

const totals = { equity: 0, debt: 0, gold: 0, cash: 0 };
let grandTotal = 0;
holdings.forEach(h => {
  const v = Number(h.current_value) || 0;
  totals[classify(h.type)] += v;
  grandTotal += v;
});
const pct = k => grandTotal > 0 ? Number(((totals[k] / grandTotal) * 100).toFixed(1)) : 0;

const targetDate = new Date(d.goal?.target_date);
const monthsToGoal = Math.max(1, Math.round((targetDate - new Date()) / (1000 * 60 * 60 * 24 * 30.44)));
const years = monthsToGoal / 12;

// ---------------------------------------------------------------- risk plan
const LEVELS = ['Low', 'Medium', 'High'];
const stated = LEVELS.includes(d.profile?.risk_appetite) ? d.profile.risk_appetite : 'Medium';
const reasons = [];

// 1. Time horizon caps the risk the goal can carry, whatever the appetite.
const horizonCap = years < 3 ? 'Low' : years < 5 ? 'Medium' : 'High';
let effective = LEVELS[Math.min(LEVELS.indexOf(stated), LEVELS.indexOf(horizonCap))];
if (effective !== stated) {
  reasons.push(years < 3
    ? `Your goal is ${years.toFixed(1)} years away - money needed that soon should not sit in shares, so we plan at Low risk.`
    : `Your goal is ${years.toFixed(1)} years away - enough for mutual funds, but too short to ride out a deep market fall, so we plan at Medium risk.`);
}

// 2. Direct stocks need a safety net first (emergency fund, health cover, no expensive loans).
const efMonths = Number(d.emergency_fund?.months_of_expenses_covered) || 0;
const expenses = Number(d.emergency_fund?.monthly_essential_expenses) || 0;
const healthCover = (d.insurance || []).filter(i => /health|medic/i.test(i.type || ''))
  .reduce((s, i) => s + (Number(i.sum_assured) || 0), 0);
const costlyLoans = (d.liabilities || []).filter(l => (Number(l.interest_rate) || 0) > 12);
const blockers = [];
if (efMonths < 3) blockers.push(`Build your emergency fund to at least 3 months of expenses (${fmtShort(expenses * 3, cur)}) - you have ${efMonths} months today.`);
if (healthCover <= 0) blockers.push('Get health insurance - one hospital bill could force you to sell shares at a loss.');
if (costlyLoans.length) blockers.push(`Clear loans above 12% interest first (${costlyLoans.map(l => `${l.type} at ${l.interest_rate}%`).join(', ')}) - they cost more than shares typically earn.`);
if (years < 3) blockers.unshift('Your goal is under 3 years away - that money should not be in shares at all, directly or through funds.');
else if (effective === 'Low') blockers.unshift('Direct stocks do not suit a Low-risk plan - equity exposure stays in diversified index funds.');
else if (years < 5) blockers.unshift('Direct stocks need at least a 5-year horizon.');
const directStocksAllowed = blockers.length === 0;

// 3. Target mix per level (percent of the portfolio).
const TARGET = {
  Low:    { equity: 15, debt: 70, gold: 10, cash: 5 },
  Medium: { equity: 50, debt: 35, gold: 10, cash: 5 },
  High:   { equity: 70, debt: 20, gold: 7,  cash: 3 },
};
let target = { ...TARGET[effective] };
if (years < 3) target = { equity: 0, debt: 85, gold: 5, cash: 10 };

const INSTRUMENTS = {
  Low:    { equity: 'Nifty 50 index fund (SIP)', debt: 'Bank FD / RD, PPF, short-term debt funds',
            gold: 'Sovereign Gold Bonds or gold ETF', cash: 'Savings account / liquid fund' },
  Medium: { equity: 'Nifty 50 index fund + large-cap / flexi-cap mutual funds', debt: 'PPF, FD / RD',
            gold: 'Sovereign Gold Bonds or gold ETF', cash: 'Liquid fund' },
  High:   { equity: 'Flexi-cap & mid-cap mutual funds + index fund', debt: 'PPF / short-duration debt funds',
            gold: 'Sovereign Gold Bonds or gold ETF', cash: 'Liquid fund' },
};
const instruments = { ...INSTRUMENTS[effective] };
if (years < 3) instruments.debt = 'Bank FD / RD matching your goal date, short-term debt funds';
// Share of the monthly amount that may go to hand-picked stocks (the rest of equity stays in funds).
const directStockSharePct = !directStocksAllowed ? 0 : effective === 'High' ? 25 : 10;

// Long-run planning returns per class; the plan's expected return is the blend of its mix.
const CLASS_RETURN = { equity: 11, debt: 7, gold: 8, cash: 4 };
const expectedReturn = Number(Object.keys(target).reduce((s, k) => s + target[k] / 100 * CLASS_RETURN[k], 0).toFixed(2));

const risk_plan = {
  stated_risk: stated,
  risk_source: d.profile?.risk_appetite ? 'user' : 'default',
  horizon_cap: horizonCap,
  effective_risk: effective,
  reasons,
  target_allocation: target,                 // percent; keys: equity, debt (= fixed income), gold, cash
  instruments,
  direct_stocks_allowed: directStocksAllowed,
  direct_stock_blockers: blockers,
  direct_stock_share_pct: directStockSharePct,
  stock_rules: directStocksAllowed ? {
    max_drawdown_pct: effective === 'High' && years >= 10 ? -45 : -35,  // no deeper fall than this
    max_volatility_pct: effective === 'High' ? 38 : 30,
    min_cagr_to_volatility: 0.5,                                       // growth must be >= half the swing
    max_per_sector: 2,
  } : null,
  class_return_assumptions_pct: CLASS_RETURN,
  expected_return_pct: expectedReturn,
};

return [{ json: {
  currency: cur,
  holdings: holdings.map(({ _raw, ...h }) => h),
  totalPortfolioValue: grandTotal,
  totalsByClass: totals,
  currentAllocation: {
    equity_pct: pct('equity'), debt_pct: pct('debt'),
    gold_pct: pct('gold'), cash_pct: pct('cash'),
  },
  ageBasedHeuristicEquityTargetPct: Math.max(0, Math.min(100, 100 - age)),
  monthsToGoal,
  yearsToGoal: Number(years.toFixed(1)),
  goal: d.goal,
  monthlyContribution: d.derived?.monthlyContrib || 0,
  risk_plan,
}}];

