// FV = P(1+r)^n + PMT * (((1+r)^n - 1) / r).  All report numbers originate here, never in an LLM.
const d    = $('Restore User State').first().json;
const alloc = $('Compute Allocation Metrics').first().json;
const debt  = $('Compute Debt Metrics').first().json;

const currentCorpus      = alloc.totalPortfolioValue || 0;
const monthlyContribution = alloc.monthlyContribution || 0;
const months = alloc.monthsToGoal;

const plan = alloc.risk_plan;
const assumedAnnualReturnPct = plan.expected_return_pct;   // blend of the risk plan's target mix
const assumedInflationPct    = 6;
const r = assumedAnnualReturnPct / 100 / 12;

const fvAt = (m, pmt) => { const g = Math.pow(1 + r, m); return currentCorpus * g + pmt * ((g - 1) / r); };
const growth = Math.pow(1 + r, months);
const fv     = fvAt(months, monthlyContribution);
const target = Number(d.goal?.target_amount) || 0;
const gap    = Number((fv - target).toFixed(2));
const requiredPmt = Math.max(0, (target - currentCorpus * growth) / ((growth - 1) / r));
const inflationAdjustedTarget = target * Math.pow(1 + assumedInflationPct / 100, months / 12);

const emergencyStatus = !d.emergency_fund?.has_fund ? 'none'
  : (d.emergency_fund.months_of_expenses_covered >= 6 ? 'adequate' : 'insufficient');

let verdict = 'on_track';
if (gap < 0) verdict = Math.abs(gap) > target * 0.15 ? 'large_gap' : 'small_gap';

// Year-by-year path for the projection chart: at today's contribution vs at the required one.
const series = [];
const steps = Math.max(1, Math.ceil(months / 12));
for (let y = 0; y <= steps; y++) {
  const m = Math.min(y * 12, months);
  series.push({ month: m, current_path: Math.round(fvAt(m, monthlyContribution)), required_path: Math.round(fvAt(m, requiredPmt)) });
  if (m === months) break;
}

const cur = d.profile?.currency || 'INR';
const salary = Number(d.profile?.current_monthly_salary) || 0;
const expenses = Number(d.emergency_fund?.monthly_essential_expenses) || 0;

// ---------------- monthly plan: where each rupee goes, by instrument ----------------
// 1) money left after essentials and EMIs, 2) emergency-fund top-up first (reach 6 months within
// about a year, never more than 40% of what is left), 3) the goal amount split by the risk plan.
const round100 = x => Math.max(0, Math.round(x / 100) * 100);
const available = Math.max(0, Number(d.derived?.surplus) || 0);
const efGap = Math.max(0, expenses * 6 - (Number(d.emergency_fund?.current_amount) || 0));
const efTopup = efGap > 0 ? round100(Math.min(efGap / 12, available * 0.4)) : 0;
const investable = Math.max(0, available - efTopup);
const goalMonthly = round100(Math.min(investable, requiredPmt));
const t = plan.target_allocation;
const equityAmt = goalMonthly * t.equity / 100;
const stockAmt = round100(Math.min(equityAmt, goalMonthly * plan.direct_stock_share_pct / 100));
const monthly_plan = [
  { bucket: 'Emergency fund top-up', instrument: 'Liquid fund / savings account', amount: efTopup },
  { bucket: 'Fixed income', instrument: plan.instruments.debt, amount: round100(goalMonthly * t.debt / 100) },
  { bucket: 'Mutual funds', instrument: plan.instruments.equity, amount: round100(equityAmt - stockAmt) },
  { bucket: 'Direct stocks', instrument: 'NIFTY 50 shortlist below', amount: stockAmt },
  { bucket: 'Gold', instrument: plan.instruments.gold, amount: round100(goalMonthly * t.gold / 100) },
  { bucket: 'Cash buffer', instrument: plan.instruments.cash, amount: round100(goalMonthly * t.cash / 100) },
].filter(x => x.amount > 0);
const planTotal = monthly_plan.reduce((s, x) => s + x.amount, 0);
const annualIncome = Number(d.profile?.annual_ctc) || salary * 12;
const cover = re => (d.insurance || []).filter(i => re.test(String(i.type || '').toLowerCase()))
  .reduce((s, i) => s + (Number(i.sum_assured) || 0), 0);

return [{ json: {
  currency: cur,
  user_name: d.profile?.user_name,
  snapshot: {
    annual_ctc: d.profile?.annual_ctc || null,
    monthly_salary: salary,
    in_hand_source: d.profile?.in_hand_source || 'user_confirmed',
    monthly_expenses: expenses,
    monthly_surplus: d.derived?.surplus || 0,
    monthly_investing: monthlyContribution,
    risk_appetite: plan.stated_risk,
    risk_effective: plan.effective_risk,
    free_cash_after_investing: (d.derived?.surplus || 0) - monthlyContribution,
    savings_rate_pct: d.derived?.savingsRatePct,
    net_worth: d.derived?.netWorth || 0,
    total_liabilities: debt.totalDebt,
    total_emi: debt.totalEmi,
    debt_to_income_pct: debt.debtToIncomeRatioPct,
    weighted_interest_pct: debt.weightedAverageInterestRate,
    total_savings_investments: currentCorpus,
    totals_by_class: alloc.totalsByClass,
    asset_allocation: alloc.currentAllocation,
    emergency_fund_amount: Number(d.emergency_fund?.current_amount) || 0,
    emergency_fund_target: expenses * 6,
    emergency_fund_status: emergencyStatus,
    months_of_expenses_covered: d.emergency_fund?.months_of_expenses_covered || 0,
    insurance_present: (d.insurance || []).length > 0,
    term_cover: cover(/term|life/),
    recommended_term_cover: annualIncome * 10,
    health_cover: cover(/health|medic/),
    recommended_health_cover: cur === 'INR' ? 1000000 : null,
  },
  future_projection: {
    target_amount: target,
    target_date: d.goal?.target_date,
    months_remaining: months,
    years_remaining: alloc.yearsToGoal,
    current_corpus: currentCorpus,
    current_monthly_contribution: monthlyContribution,
    assumptions: { expected_annual_return_pct: assumedAnnualReturnPct, inflation_pct: assumedInflationPct },
    projected_value_at_target_date: Number(fv.toFixed(2)),
    inflation_adjusted_target: Number(inflationAdjustedTarget.toFixed(2)),
    on_track: gap >= 0,
    verdict,
    gap_or_surplus: gap,
    progress_pct: target > 0 ? Number(Math.min(100, (fv / target) * 100).toFixed(1)) : 0,
    required_monthly_contribution_to_hit_goal: Number(requiredPmt.toFixed(2)),
    additional_monthly_needed: Number(Math.max(0, requiredPmt - monthlyContribution).toFixed(2)),
    series,
  },
  risk_plan: plan,
  monthly_plan: {
    available_after_essentials_and_emi: available,
    emergency_topup: efTopup,
    goal_investment: goalMonthly,
    total: planTotal,
    unallocated: Math.max(0, available - planTotal),
    goal_underfunded_by: Math.max(0, Math.round(requiredPmt - goalMonthly)),
    rows: monthly_plan,
  },
  debt_analysis: $('Debt Analysis Agent').first().json.output,
  portfolio_analysis: $('Portfolio Analysis Agent').first().json.output,
}}];

