    const dd = Number(st.max_drawdown_pct), vol = Number(st.annualized_volatility_pct), cagr = Number(st.five_year_cagr_pct);
    const why = [];
    if (!Number.isFinite(dd) || !Number.isFinite(vol) || !Number.isFinite(cagr)) why.push('figures missing from the dataset');
    else {
      if (-Math.abs(dd) < rules.max_drawdown_pct) why.push(`worst fall ▼${Math.abs(dd).toFixed(1)}% is deeper than your ▼${Math.abs(rules.max_drawdown_pct)}% limit`);
      if (vol > rules.max_volatility_pct) why.push(`swings of ${vol.toFixed(1)}% a year exceed your ${rules.max_volatility_pct}% limit`);
      if (cagr < vol * rules.min_cagr_to_volatility) why.push(`growth of ${cagr.toFixed(1)}% a year is too low for ${vol.toFixed(1)}% swings`);
    }
    const sec = String(st.sector || '').toLowerCase();
    if (!why.length && (perSector[sec] || 0) >= rules.max_per_sector) why.push(`already ${rules.max_per_sector} picks from ${st.sector}`);
    if (why.length) dropped.push({ ...st, why });
    else { shortlist.push(st); perSector[sec] = (perSector[sec] || 0) + 1; }
  }
