    <div class="grid" style="margin-top:14px">
      ${tile('You pay in', money(dp.total_paid), 'monthly instalments', 'var(--muted)')}
      ${tile('Value by goal date', money(dp.value_on_goal_date), 'before tax', 'var(--c-debt)')}
      ${tile('Fixed-income share to fund', money(dp.goal_share), plan.target_allocation.debt + '% of what your monthly saving must build', 'var(--s1)')}
    </div>
    <p>${dp.reached ? `This <strong>covers</strong> the fixed-income share of your goal (your current investments cover the rest of the target as they grow).`
      : `This <strong>falls short</strong> of the fixed-income share. About <strong>${esc(money(dp.installment_needed))} a month</strong> in these deposits would cover it.`}</p>
    ${dp.alternatives && dp.alternatives.length ? `<p class="ab-legend">Single-bank alternatives: ${dp.alternatives.map(a => `${esc(a.bank)} ${esc(a.tenor)} @ ${Number(a.rate_pct).toFixed(2)}% → ${esc(money(a.value))}`).join(' · ')}.</p>` : ''}
    <p class="ab-legend">Card rates from the team's bank documents${dp.as_of ? ` (as of ${esc(dp.as_of)})` : ''} - confirm with the bank before opening.
      Interest is taxable; values are before tax. Matured deposits are kept, not reinvested.</p>
  </div>`;
  })()}

  <h2>What you own vs what you owe</h2>
  <div class="card">
    <div class="row-label"><span>You own</span><strong>${esc(money(ownTotal))}</strong></div>
    <div style="width:${(ownTotal / scaleMax * 100).toFixed(1)}%">${stackBar(ownParts, ownTotal)}</div>
    <div class="row-label"><span>You owe</span><strong>${esc(money(oweTotal))}</strong></div>
    ${oweTotal > 0 ? `<div style="width:${(oweTotal / scaleMax * 100).toFixed(1)}%">${stackBar(loans, oweTotal)}</div>
      <div class="ab-legend">Grey<span style="background:var(--neutral)"></span>loans at 12% or less · Red<span style="background:var(--critical)"></span>above 12% interest - pay these first</div>` : '<div class="muted" style="font-size:14px">Nothing - you are debt-free 🎉</div>'}
    ${legend(ownParts.filter(p => p.value > 0), ownTotal)}
  </div>

  <h2>Asset allocation · now vs your ${esc(plan.effective_risk.toLowerCase())}-risk target</h2>
  <div class="card alloc">
    ${donut(classParts, short(snap.total_savings_investments), 'invested')}
    <div>
      ${allocBars}
      <div class="ab-legend">Faded bar<span style="opacity:.45"></span>now · Solid bar<span></span>suggested</div>
    </div>
  </div>
  <div class="card">
    <div class="table-wrap"><table>
      <thead><tr><th>Asset class</th><th class="num">Now</th><th class="num">Suggested</th><th class="num">Change</th><th>Why</th></tr></thead>
      <tbody>${allocRows || '<tr><td colspan="5" class="muted">No allocation advice generated.</td></tr>'}</tbody>
    </table></div>
  </div>

  <h2>Safety-net check</h2>
  <div class="meters">${metersHtml}</div>

  ${loans.length ? `
  <h2>Your loans</h2>
  <div class="card">
    ${loans.slice().sort((a, b) => b.rate - a.rate).map(l => `<div class="debt-row">
      <div>${esc(l.key)}${l.rate > 12 ? ' <span class="badge" style="--b:var(--critical)"><b>!</b> pay first</span>' : ''}</div>
      <div class="debt-bar" title="${esc(l.key)}: ${esc(money(l.value))}, EMI ${esc(money(l.emi))}"><span style="width:${(l.value / oweTotal * 100).toFixed(1)}%;background:${l.color}"></span></div>
      <div class="num">${esc(short(l.value))}</div></div>`).join('')}
    ${r.debt_commentary ? `<p style="margin-top:14px">${esc(r.debt_commentary)}</p>` : ''}
  </div>` : (r.debt_commentary ? `<h2>Debt</h2><div class="card"><p>${esc(r.debt_commentary)}</p></div>` : '')}

  <h2>Do these first</h2>
  <div class="card"><ol class="actions">${actions || '<li class="muted">No actions generated.</li>'}</ol></div>

  ${!plan.direct_stocks_allowed ? `
  <h2>Direct stocks · not yet</h2>
  <div class="card">
    <p>Individual shares can fall 30-50% in a bad year. ${plan.effective_risk === 'Low' ? 'They are not part of your plan:' : 'They unlock once these are in place:'}</p>
    <ul class="bad">${plan.direct_stock_blockers.map(x => `<li>${esc(x)}</li>`).join('')}</ul>
    ${dropped.length ? `<p class="ab-legend">The market screen suggested ${dropped.map(x => esc(x.symbol)).join(', ')} - held back until then.</p>` : ''}
  </div>` : equityRows ? `
  <h2>Equity shortlist · ${esc(money(stockMonthly))}/month</h2>
  <div class="card">
    <p><strong>${esc(money(stockMonthly))} a month</strong> (${plan.direct_stock_share_pct}% of your goal investment) can go to the stocks below, split evenly;
      the rest of your equity stays in mutual funds. ${r.equity_sleeve_note && !/\d/.test(r.equity_sleeve_note) ? esc(r.equity_sleeve_note) : ''}</p>
    <p class="ab-legend">Your ${esc(plan.effective_risk)}-risk limits: worst fall no deeper than ▼${Math.abs(rules.max_drawdown_pct)}%,
      yearly swing up to ${rules.max_volatility_pct}%, growth at least half the swing, max ${rules.max_per_sector} per sector.</p>
    <div class="table-wrap"><table>
      <thead><tr><th>Stock</th><th>Sector</th><th class="num">5-yr CAGR<br><span class="sub">avg yearly growth</span></th><th class="num">Volatility<br><span class="sub">yearly swing</span></th><th class="num">Worst fall<br><span class="sub">max drawdown</span></th><th>Why this one</th></tr></thead>
      <tbody>${equityRows}</tbody>
    </table></div>
    <p class="ab-legend"><strong>How to read this:</strong> <em>5-yr CAGR</em> is the average yearly growth over five years.
    <em>Volatility</em> is how much the price typically swings in a year. <em>Worst fall (max drawdown)</em> is the
    biggest drop from a high to a later low - e.g. ▼ 33.4% means ₹1,00,000 invested at the peak fell to about
    ₹66,600 before recovering. It is a loss, which is why it is often written as a negative number.</p>
    ${dropped.length ? `<p class="ab-legend"><strong>Removed by your risk limits:</strong> ${dropped.map(x => `${esc(x.symbol)} (${esc(x.why.join('; '))})`).join(' · ')}</p>` : ''}
    <p class="caveat"><strong>Read this before acting.</strong> These names were screened from the
    NIFTY 50 historical dataset (period ending 26 Aug 2026) on past return and risk alone. Past
    performance does not predict future returns, the figures are not live prices, and this is not a
    recommendation to buy. Direct equity belongs in the satellite part of a portfolio, never the core.</p>
  </div>` : `<h2>Direct stocks</h2><div class="card"><p>No NIFTY 50 name passed your ${esc(plan.effective_risk)}-risk limits${dropped.length ? ': ' + dropped.map(x => `${esc(x.symbol)} (${esc(x.why.join('; '))})`).join(' · ') : ''}. Keep the equity part in mutual funds for now.</p></div>`}

  <h2>Strengths and risks</h2>
  <div class="card two-col">
    <div><strong>Working in your favour</strong>${bullets(r.strengths, 'good')}</div>
    <div><strong>Watch out for</strong>${bullets(r.risks, 'bad')}</div>
  </div>

  <details class="data"><summary>Show the numbers behind the charts</summary>
    <div class="card" style="margin-top:8px"><div class="table-wrap"><table>
      <thead><tr><th>Year</th><th class="num">At your current SIP</th><th class="num">At the required SIP</th></tr></thead>
      <tbody>${(proj.series || []).map(p => `<tr><td>${yearAt(p.month)}</td>
        <td class="num">${esc(money(p.current_path))}</td><td class="num">${esc(money(p.required_path))}</td></tr>`).join('')}</tbody>
    </table></div></div>
  </details>

  <div class="disclaimer">
    <strong>Assumptions:</strong> ${esc([
      `${proj.assumptions.expected_annual_return_pct}% expected annual return (${plan.effective_risk}-risk mix: equity ${plan.class_return_assumptions_pct.equity}%, fixed income ${plan.class_return_assumptions_pct.debt}%, gold ${plan.class_return_assumptions_pct.gold}%, cash ${plan.class_return_assumptions_pct.cash}%)`,
      `${proj.assumptions.inflation_pct}% inflation`,
      // the model's own extra assumptions, minus any return/inflation figure that could contradict the computed one
      ...(r.assumptions || []).filter(x => !/return|inflation/i.test(x)),
    ].join(' · '))}${
      snap.in_hand_source === 'estimated_from_ctc' ? ' · In-hand pay estimated from CTC (new tax regime, FY 2026-27).' : ''}<br><br>
    This report is educational information generated from the figures you supplied and a historical
    market dataset. It is not licensed financial advice, and past performance does not predict future
    returns. Please consult a registered adviser before acting on it.
  </div>
</div></div>`;

return [{ json: { report_html: html, report_structured: r, computed: src } }];

// Single base64 parameter - no comma-splitting hazard from free-text goals or names.
const render = $('Render Report Card').first().json;
const d      = $('Restore User State').first().json;

const payload = {
  session_id: d.session_id,
  user_key: d.user_key,
  question: d.goal?.description || '',
  report: {
    computed: render.computed,
    narrative: render.report_structured,
    html: render.report_html,
    source_dataset: 'NIFTY50 historical bundle through 2026-08-26',
    generated_at: new Date().toISOString(),
    user_name: d.profile?.user_name || '',
    change_log: d.change_log || [],
    parent: d.parent_report || null,
  },
  pending_id: d.pending_id || null,
};
return [{ json: { advice_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64') } }];

parameters.query:
SELECT created_at, question, report_json #- '{html}' AS report
FROM advice_sessions WHERE user_key = $1
ORDER BY created_at DESC LIMIT 1;

parameters.jsCode:
// ---- shared helpers (inlined into each Code node by the builder) ----

// Accepts what people actually type: 85000, 85,000, "85K", "1.2L", "2.5 lakh", "3Cr",
// "Rs 12,00,000". Returns a number, or null if it cannot be understood - null is deliberate:
// `Check Profile Completeness` then asks the user instead of silently using 0.
function parseAmount(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  let s = String(v).toLowerCase().trim();
  if (!s) return null;
  s = s.replace(/[₹$€£¥,\s_]/g, '').replace(/^(rs\.?|inr|usd|eur|gbp|aed|sgd)/, '');
  const m = s.match(/^(-?\d+(?:\.\d+)?)(.*)$/);
  if (!m) return null;
  const n = parseFloat(m[1]);
  if (!Number.isFinite(n)) return null;
  const suffix = m[2].replace(/[^a-z]/g, '');
  const mult =
    suffix === ''                                              ? 1    :
    /^(c|cr|crs|crore|crores)$/.test(suffix)                   ? 1e7  :
    /^(l|lk|lac|lacs|lakh|lakhs)$/.test(suffix)                ? 1e5  :
    /^(k|th|thousand|thousands)$/.test(suffix)                 ? 1e3  :
    /^(m|mn|million|millions)$/.test(suffix)                   ? 1e6  :
    /^(b|bn|billion|billions)$/.test(suffix)                   ? 1e9  :
    /^(pa|pm|permonth|peryear|month|year|yr|mo)$/.test(suffix) ? 1    :
    null;
  return mult === null ? null : n * mult;
}

// Optional amount: blank means 0, anything typed but unreadable means null.
function parseOptional(v) {
  if (v === null || v === undefined || String(v).trim() === '') return 0;
  return parseAmount(v);
}

// Interest rates are never scaled - "8.5%", "8.5 % p.a." and "8.5" all mean 8.5.
function parseRate(v) {
  if (v === null || v === undefined || String(v).trim() === '') return null;
  const n = parseFloat(String(v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
}

const esc = s => String(s ?? '').replace(/[&<>"']/g, c =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const trim2 = x => String(Math.round(x * 100) / 100);

// Friendly short money for chat bubbles: ₹1.22L, ₹18L, ₹1.5Cr, $85K.
function fmtShort(n, cur) {
  const v = Number(n) || 0;
  const sign = v < 0 ? '-' : '';
  const a = Math.abs(v);
  if (!cur || cur === 'INR') {
    if (a >= 1e7) return sign + '₹' + trim2(a / 1e7) + 'Cr';
    if (a >= 1e5) return sign + '₹' + trim2(a / 1e5) + 'L';
    if (a >= 1e3) return sign + '₹' + trim2(a / 1e3) + 'K';
    return sign + '₹' + Math.round(a);
  }
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: cur,
      notation: 'compact', maximumFractionDigits: 1 }).format(v);
  } catch (e) { return cur + ' ' + Math.round(v); }
}

// Value to pre-fill an input with. Uses K/L/Cr shorthand only when it is exact,
// so re-submitting a pre-filled form never changes the stored number.
function shorthand(n, cur) {
  if (n === null || n === undefined || n === '') return '';
  const v = Number(n);
  if (!Number.isFinite(v)) return String(n);
  if (v === 0) return '0';
  if (!cur || cur === 'INR') {
    for (const [div, suf] of [[1e7, 'Cr'], [1e5, 'L'], [1e3, 'K']]) {
      if (Math.abs(v) >= div && Math.abs(Math.round((v / div) * 100) / 100 * div - v) < 0.5) return trim2(v / div) + suf;
    }
  }
  return String(Math.round(v * 100) / 100);
}

const firstName = full => String(full || '').trim().split(/\s+/)[0] || 'there';

const monthsUntil = (dateStr) => {
  const t = new Date(dateStr);
  if (!dateStr || isNaN(t.getTime())) return null;
  return Math.round((t - new Date()) / (1000 * 60 * 60 * 24 * 30.44));
};

const monthYear = (dateStr) => {
  const t = new Date(dateStr);
  return isNaN(t.getTime()) ? String(dateStr || '') :
    t.toLocaleDateString('en-GB', { month: 'short', year: 'numeric' });
};

// Rough annual CTC -> monthly in-hand for India, FY 2026-27 new tax regime.
// Assumptions (shown to the user, who confirms or corrects the figure):
// basic = 40% of CTC, employer + employee PF = 12% of basic each, gratuity = 4.81% of basic,
// standard deduction 75,000, section 87A rebate up to 12L taxable, 4% cess, professional tax 2,500.
function estimateInHand(ctc, cur) {
  const c = Number(ctc) || 0;
  if (c <= 0) return null;
  if (cur && cur !== 'INR') return Math.round((c * 0.72) / 12 / 100) * 100;  // generic rough cut
  const basic = c * 0.40;
  const employerPf = basic * 0.12, gratuity = basic * 0.0481, employeePf = basic * 0.12;
  const gross = c - employerPf - gratuity;
  const taxable = Math.max(0, gross - 75000);
  const slabs = [[400000, 0], [800000, 0.05], [1200000, 0.10], [1600000, 0.15],
                 [2000000, 0.20], [2400000, 0.25], [Infinity, 0.30]];
  let tax = 0, prev = 0;
  for (const [upto, rate] of slabs) {
    if (taxable > prev) tax += (Math.min(taxable, upto) - prev) * rate;
    prev = upto;
  }
  if (taxable <= 1200000) tax = 0;                                  // 87A rebate
  else tax = Math.min(tax, taxable - 1200000);                      // marginal relief
  const surcharge = taxable > 2e7 ? 0.25 : taxable > 1e7 ? 0.15 : taxable > 5e6 ? 0.10 : 0;
  tax = tax * (1 + surcharge) * 1.04;
  const net = gross - employeePf - tax - 2500;
  return Math.round(net / 12 / 500) * 500;
}

// Everything downstream reads `derived`; recompute it from the canonical profile.
function computeDerived(d) {
  const salary = Number(d.profile?.current_monthly_salary) || 0;
  const monthlyExpenses = Number(d.emergency_fund?.monthly_essential_expenses) || 0;
  const emergency = Number(d.emergency_fund?.current_amount) || 0;
  const totalEmi = (d.liabilities || []).reduce((s, l) => s + (Number(l.emi) || 0), 0);
  const totalDebt = (d.liabilities || []).reduce((s, l) => s + (Number(l.outstanding_amount) || 0), 0);
  const totalSavingsValue = (d.savings_investments || []).reduce((s, i) => s + (Number(i.current_value) || 0), 0);
  const monthlyContrib = (d.savings_investments || []).reduce((s, i) => s + (Number(i.monthly_contribution) || 0), 0);
  const surplus = salary - totalEmi - monthlyExpenses;
  d.emergency_fund = d.emergency_fund || {};
  d.emergency_fund.has_fund = emergency > 0;
  d.emergency_fund.months_of_expenses_covered = monthlyExpenses > 0
    ? Number((emergency / monthlyExpenses).toFixed(1)) : 0;
  d.derived = {
    totalEmi, totalDebt, totalSavingsValue, monthlyContrib,
    emergencyFund: emergency,
    netWorth: totalSavingsValue + emergency - totalDebt,
    surplus,
    freeCashAfterInvesting: surplus - monthlyContrib,
    savingsRatePct: salary > 0 ? Number(((surplus / salary) * 100).toFixed(1)) : null,
  };
  return d;
}

// The advisor's chat bubble at the top of every conversational page.
// n8n strips style/class attributes from form HTML, so the look comes from FORM_CSS.
const bubble = (heading, paragraphs) =>
  `<h3>${heading}</h3>` + paragraphs.filter(Boolean).map(p => `<p>${p}</p>`).join('');

const LOAN_TYPES = ['Home loan', 'Car loan', 'Personal loan', 'Education loan',
                    'Credit card dues', 'Gold loan', 'Other loan'];
const NO_LOANS = "None - I'm debt-free";
// Risk appetite: answered as a gut reaction to a fall, stored as Low / Medium / High.
const RISK_OPTIONS = {
  Low:    "Low - I'd sell to stop the loss. Keep my money safe, even if it grows slowly (FDs, PPF)",
  Medium: "Medium - I'd wait for it to recover. Some ups and downs are fine (mostly mutual funds)",
  High:   "High - I'd invest more while it's cheap. I'm fine with big swings (funds + stocks)",
};
const riskFromAnswer = a => (String(a || '').match(/^(Low|Medium|High)\b/) || [])[1] || null;
const slug = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');

// ---- v3.4 helpers (appended to the shared helpers by tools/build_v34.py) ----

const GOALS = ['Buy a home', 'Retirement', "Child's education", "Child's wedding", 'Buy a car',
               'Start a business', 'Travel or sabbatical', 'Build long-term wealth', 'Other'];
const CURRENCIES = ['INR', 'USD', 'EUR', 'GBP', 'AED', 'SGD'];
const INVESTMENT_KEYS = ['mf', 'stocks', 'gold', 'fd', 'pf', 'cash', 'other'];
const VERDICT_LABEL = { on_track: 'On track', small_gap: 'Slightly behind', large_gap: 'Significant gap' };

// A report id nobody can guess (it is the only key to a report page).
function newReportId() {
  const c = globalThis.crypto;
  if (c && typeof c.randomUUID === 'function') return c.randomUUID().replace(/-/g, '');
  let s = '';
  while (s.length < 32) s += Math.random().toString(16).slice(2);
  return s.slice(0, 32);
}

// The step form's answers (strings as typed) for a saved profile. v3.4 profiles keep the raw answers;
// older ones (v2 / v3 forms) are mapped back the same way the old "Evaluate Journey" node did.
function answersFromProfile(saved) {
  if (typeof saved === 'string') { try { saved = JSON.parse(saved); } catch (e) { saved = {}; } }
  saved = saved || {};
  if (saved.form_answers && saved.form_answers.raw) return JSON.parse(JSON.stringify(saved.form_answers.raw));
  const fa = saved.form_answers || {};
  const cur = saved.profile?.currency || 'INR';
  const pick = (...vals) => vals.find(v => v !== undefined && v !== null && v !== '') ?? '';
  const loanBucket = t => {
    t = String(t || '').toLowerCase();
    if (/home|house|housing|mortgage/.test(t)) return 'Home loan';
    if (/car|vehicle|auto|bike/.test(t)) return 'Car loan';
    if (/educat|student/.test(t)) return 'Education loan';
    if (/credit|card/.test(t)) return 'Credit card dues';
    if (/gold/.test(t)) return 'Gold loan';
    if (/personal/.test(t)) return 'Personal loan';
    return 'Other loan';
  };
  const invBucket = t => {
    t = String(t || '').toLowerCase();
    if (/mutual|\bmf\b|sip|elss|index|etf|fund/.test(t) && !/gold/.test(t)) return 'mf';
    if (/gold|sgb|silver/.test(t)) return 'gold';
    if (/stock|share|equity|demat/.test(t)) return 'stocks';
    if (/\bfd\b|\brd\b|fixed|recurring|deposit|bond/.test(t)) return 'fd';
    if (/ppf|epf|vpf|provident/.test(t)) return 'pf';
    if (/saving|cash|bank|liquid/.test(t)) return 'cash';
    return 'other';
  };
  let loans = fa.loans;
  if (!loans) {
    loans = {};
    (saved.liabilities || []).forEach(l => {
      const b = loanBucket(l.type);
      const o = loans[b] || { outstanding: 0, rate: 0, emi: 0, _w: 0 };
      const amt = Number(l.outstanding_amount) || 0;
      o.outstanding += amt; o.emi += Number(l.emi) || 0; o._w += amt * (Number(l.interest_rate) || 0);
      o.rate = o.outstanding > 0 ? Number((o._w / o.outstanding).toFixed(2)) : Number(l.interest_rate) || 0;
      loans[b] = o;
    });
  }
  let inv = fa.investments;
  if (!inv) {
    inv = {};
    (saved.savings_investments || []).forEach(s => {
      const b = invBucket(s.type);
      inv[b + '_value'] = (Number(inv[b + '_value']) || 0) + (Number(s.current_value) || 0);
      inv[b + '_monthly'] = (Number(inv[b + '_monthly']) || 0) + (Number(s.monthly_contribution) || 0);
      if (b === 'other' && !inv.other_label) inv.other_label = s.type;
    });
  }
  const insOf = re => (saved.insurance || []).filter(i => re.test(String(i.type || '').toLowerCase()));
  const sum = (arr, k) => arr.reduce((s, x) => s + (Number(x[k]) || 0), 0);
  const termIns = insOf(/term|life/), healthIns = insOf(/health|medic|mediclaim/);
  const desc = String(saved.goal?.description || '').toLowerCase();
  const goalType = saved.goal?.goal_type || (!desc ? '' : /house|home|flat|property/.test(desc) ? 'Buy a home'
    : /retire/.test(desc) ? 'Retirement' : /educat|college|school/.test(desc) ? "Child's education"
    : /wedding|marriage/.test(desc) ? "Child's wedding" : /car|vehicle/.test(desc) ? 'Buy a car'
    : /business|startup/.test(desc) ? 'Start a business' : /travel|sabbatical|trip/.test(desc) ? 'Travel or sabbatical'
    : /wealth|corpus|invest/.test(desc) ? 'Build long-term wealth' : 'Other');
  const sh = v => shorthand(v, cur);
  const loanAnswers = {};
  for (const [t, l] of Object.entries(loans)) loanAnswers[t] = { outstanding: sh(l.outstanding), rate: l.rate ? String(l.rate) : '', emi: sh(l.emi) };
  const invAnswers = { other_label: inv.other_label || '' };
  for (const k of INVESTMENT_KEYS) { invAnswers[`${k}_value`] = sh(inv[`${k}_value`]); invAnswers[`${k}_monthly`] = sh(inv[`${k}_monthly`]); }
  return {
    user_name: pick(saved.profile?.user_name), age: pick(saved.profile?.age), currency: cur,
    annual_ctc: sh(saved.profile?.annual_ctc), goal_type: goalType,
    goal_details: pick(saved.goal?.details, goalType === 'Other' ? saved.goal?.description : ''),
    target_amount: sh(saved.goal?.target_amount), target_date: pick(saved.goal?.target_date),
    take_home: sh(saved.profile?.current_monthly_salary), expenses: sh(saved.emergency_fund?.monthly_essential_expenses),
    emergency: sh(saved.emergency_fund?.current_amount),
    term_cover: sh(pick(fa.term_cover, termIns.length ? sum(termIns, 'sum_assured') : '')),
    term_premium: sh(pick(fa.term_premium, termIns.length ? sum(termIns, 'premium_annual') : '')),
    health_cover: sh(pick(fa.health_cover, healthIns.length ? sum(healthIns, 'sum_assured') : '')),
    health_premium: sh(pick(fa.health_premium, healthIns.length ? sum(healthIns, 'premium_annual') : '')),
    loan_types: saved.profile ? (Object.keys(loans).length ? Object.keys(loans) : [NO_LOANS]) : [],
    loans: loanAnswers, investments: invAnswers,
    risk: saved.profile?.risk_appetite || '',
  };
}

// A plan change asked for in the chat, applied to the step-form answers (port of the Python app's
// apply_changes). Returns { answers, log, ignored }; answers is null when nothing would change.
function applyPlanChanges(answers, changes) {
  const a = JSON.parse(JSON.stringify(answers || {}));
  const cur = a.currency || 'INR';
  const log = [], ignored = [];
  const amt = (label, v) => { const n = parseAmount(v); if (n === null || n < 0) { ignored.push(`${label} (could not read "${v}")`); return null; } return n; };
  const setAmount = (field, label, v, current) => {
    const n = amt(label, v); if (n === null) return;
    if (current !== null && current !== undefined && Math.abs(Number(current) - n) < 0.5) { ignored.push(`${label} is already ${fmtShort(n, cur)}`); return; }
    log.push(`${label} ${fmtShort(current || 0, cur)} → ${fmtShort(n, cur)}`);
    a[field] = shorthand(n, cur);
  };
  a.investments = a.investments || {};
  for (const [k, v] of Object.entries(changes || {})) {
    if (v === null || v === undefined || v === '') continue;
    if (k === 'monthly_sip_total') {
      const n = amt('monthly investing', v); if (n === null) continue;
      const inv = a.investments;
      const before = INVESTMENT_KEYS.reduce((s, key) => s + (parseOptional(inv[`${key}_monthly`]) || 0), 0);
      if (Math.abs(before - n) < 0.5) { ignored.push(`Monthly investing is already ${fmtShort(n, cur)}`); continue; }
      if (n > before) inv.mf_monthly = shorthand((parseOptional(inv.mf_monthly) || 0) + (n - before), cur);   // the extra goes to mutual funds
      else {
        const f = before ? n / before : 0;                                                                   // scale every SIP down
        for (const key of INVESTMENT_KEYS) { const m = parseOptional(inv[`${key}_monthly`]) || 0; if (m) inv[`${key}_monthly`] = shorthand(Math.round(m * f), cur); }
      }
      log.push(`Monthly investing ${fmtShort(before, cur)} → ${fmtShort(n, cur)}`);
    } else if (k === 'target_amount') {
      const n = amt('target', v); if (n !== null && n >= 10000) setAmount('target_amount', 'Target', n, parseAmount(a.target_amount));
    } else if (k === 'target_date') {
      const s = String(v).slice(0, 10), t = new Date(s);
      if (isNaN(t.getTime()) || t <= new Date()) ignored.push('target date (must be in the future)');
      else if (s === a.target_date) ignored.push(`Target date is already ${s}`);
      else { log.push(`Target date ${a.target_date || '-'} → ${s}`); a.target_date = s; }
    } else if (k === 'risk_appetite') {
      const m = String(v).match(/low|medium|high/i);
      const r = m ? m[0][0].toUpperCase() + m[0].slice(1).toLowerCase() : '';
      if (!['Low', 'Medium', 'High'].includes(r)) ignored.push('risk (Low, Medium or High)');
      else if (r === a.risk) ignored.push(`Risk is already ${r}`);
      else { log.push(`Risk ${a.risk || 'Medium'} → ${r}`); a.risk = r; }
    } else if (k === 'take_home') setAmount('take_home', 'In-hand pay', v, parseAmount(a.take_home));
    else if (k === 'annual_ctc') setAmount('annual_ctc', 'CTC', v, parseAmount(a.annual_ctc));
    else if (k === 'expenses') setAmount('expenses', 'Essentials', v, parseAmount(a.expenses));
    else if (k === 'emergency_fund') setAmount('emergency', 'Emergency fund', v, parseOptional(a.emergency));
    else if (k === 'emergency_lumpsum') {
      const n = amt('emergency deposit', v);
      if (n) { const before = parseOptional(a.emergency) || 0; log.push(`Emergency fund ${fmtShort(before, cur)} → ${fmtShort(before + n, cur)}`); a.emergency = shorthand(before + n, cur); }
    } else if (k === 'term_cover' || k === 'health_cover') setAmount(k, k === 'term_cover' ? 'Term cover' : 'Health cover', v, parseOptional(a[k]));
    else if (k === 'remove_loan') {
      const t = (a.loan_types || []).find(x => x.toLowerCase() === String(v).toLowerCase().trim());
      if (!t) ignored.push(`remove loan (no "${v}" on file)`);
      else {
        a.loan_types = a.loan_types.filter(x => x !== t);
        if (!a.loan_types.length) a.loan_types = [NO_LOANS];
        if (a.loans) delete a.loans[t];
        log.push(`Removed ${t}`);
      }
    } else ignored.push(k);
  }
  return { answers: log.length ? a : null, log, ignored };
}

// ---- end shared helpers ----

// v3.4: the whole step form (or a confirmed chat change) -> the canonical profile every downstream node reads.
// Input: a plan request { email, journey, user_id, is_returning, answers, change_log, parent, pending_id }.
const req = $json;
const a = req.answers || {};
const email = String(req.email || '').trim().toLowerCase();
if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) throw new Error('A valid email address is required.');
const cur = a.currency || 'INR';

// ---- about you and your goal
const ctc = parseAmount(a.annual_ctc);
const target = parseAmount(a.target_amount);
const estimate = estimateInHand(ctc, cur);
const goalType = GOALS.includes(a.goal_type) ? a.goal_type : 'Other';
const details = String(a.goal_details || '').trim().slice(0, 200);
const description = goalType === 'Other' ? (details || 'Other') : (details ? `${goalType} - ${details}` : goalType);

// ---- money in, money out
const takeHome = parseAmount(a.take_home);
const expenses = parseAmount(a.expenses);

// ---- safety net
const s = {};
for (const k of ['emergency', 'term_cover', 'term_premium', 'health_cover', 'health_premium']) {
  s[k] = parseOptional(a[k]); s[`${k}_raw`] = a[k];
}

// ---- loans (only the ticked types)
let picked = Array.isArray(a.loan_types) ? a.loan_types : (a.loan_types ? [a.loan_types] : []);
picked = picked.filter(t => LOAN_TYPES.includes(t));
const loanAnswers = a.loans || {};
const liabilities = picked.map(t => {
  const l = loanAnswers[t] || {};
  const raw = [l.outstanding, l.rate, l.emi];
  const card = t === 'Credit card dues';
  const emiBlank = l.emi === null || l.emi === undefined || String(l.emi).trim() === '';
  return {
    type: t,
    outstanding_amount: parseAmount(l.outstanding),
    interest_rate: parseRate(l.rate),
    // Card dues with no fixed payment: assume the usual 5% minimum due so the EMI load is not understated.
    emi: card && emiBlank ? Math.round((parseAmount(l.outstanding) || 0) * 0.05) : parseAmount(l.emi),
    _raw: raw.filter(x => x !== null && x !== undefined && x !== '').join(' | '),
  };
});

// ---- what you already own
const INV = [['mf', 'Equity Mutual Funds'], ['stocks', 'Direct Stocks'], ['gold', 'Gold (SGB / coins / gold funds)'],
             ['fd', 'FD / RD'], ['pf', 'PPF / EPF / VPF'], ['cash', 'Savings account / cash'], ['other', null]];
const invA = a.investments || {};
const savings_investments = [];
const investments = {};
for (const [k, label] of INV) {
  const vRaw = invA[`${k}_value`], mRaw = k === 'cash' ? '' : invA[`${k}_monthly`];
  const value = parseOptional(vRaw), monthly = parseOptional(mRaw);
  investments[`${k}_value`] = value; investments[`${k}_monthly`] = monthly;
  if (value === 0 && monthly === 0) continue;
  const type = label || String(invA.other_label || '').trim().slice(0, 60) || 'Other investment';
  savings_investments.push({ type, _key: k, current_value: value, monthly_contribution: monthly,
    _raw: [type, vRaw, mRaw].filter(x => x !== null && x !== undefined && x !== '').join(' | ') });
}
investments.other_label = String(invA.other_label || '').trim().slice(0, 60);

const insurance = [];
if (s.term_cover || s.term_premium) insurance.push({ type: 'Term Life', sum_assured: s.term_cover, premium_annual: s.term_premium });
if (s.health_cover || s.health_premium) insurance.push({ type: 'Health', sum_assured: s.health_cover, premium_annual: s.health_premium });
const loansForPrefill = {};
liabilities.forEach(l => { loansForPrefill[l.type] = { outstanding: l.outstanding_amount, rate: l.interest_rate, emi: l.emi }; });
const risk = ['Low', 'Medium', 'High'].includes(a.risk) ? a.risk : (riskFromAnswer(a.risk) || 'Medium');

const d = {
  session_id: newReportId(),
  user_key: email,
  user_id: req.user_id || null,
  is_returning_user: Boolean(req.is_returning),
  profile_source: req.change_log && req.change_log.length ? 'chat_change' : (req.journey === 'update' ? 'updated' : 'new'),
  submitted_at: new Date().toISOString(),
  change_log: req.change_log || [],
  parent_report: req.parent || null,
  pending_id: req.pending_id || null,
  profile: {
    user_name: String(a.user_name || '').trim().slice(0, 80),
    email,
    age: parseAmount(a.age),
    currency: cur,
    annual_ctc: ctc,
    estimated_monthly_in_hand: estimate,
    current_monthly_salary: takeHome,
    in_hand_source: estimate && takeHome === estimate ? 'estimated_from_ctc' : 'user_confirmed',
    risk_appetite: risk,
  },
  goal: { goal_type: goalType, details, description, target_amount: target, target_date: a.target_date || null },
  liabilities,
  savings_investments,
  insurance,
  emergency_fund: { current_amount: s.emergency, monthly_essential_expenses: expenses },
  form_answers: {
    term_cover: s.term_cover, term_premium: s.term_premium, health_cover: s.health_cover, health_premium: s.health_premium,
    loans: loansForPrefill, investments,
    raw: { ...a, risk },          // the step form's answers as typed: pre-fills the next visit, and chat changes edit these
  },
};

// Anything typed that we could not read; the page shows it on the right step.
const unreadable = [];
const bad = (label, raw, path, kind) => unreadable.push({ label, raw: raw ?? '', path, kind });
if (ctc === null) bad('Current CTC (annual)', a.annual_ctc, ['profile', 'annual_ctc'], 'amount');
if (target === null) bad('Target amount', a.target_amount, ['goal', 'target_amount'], 'amount');
if (takeHome === null) bad('Monthly in-hand salary', a.take_home, ['profile', 'current_monthly_salary'], 'amount');
if (expenses === null) bad('Monthly essential expenses', a.expenses, ['emergency_fund', 'monthly_essential_expenses'], 'amount');
for (const [k, label] of [['emergency', 'Emergency fund'], ['term_cover', 'Term life cover'], ['term_premium', 'Term premium per year'],
                          ['health_cover', 'Health cover'], ['health_premium', 'Health premium per year']]) {
  if (s[k] === null) bad(label, s[`${k}_raw`], k === 'emergency' ? ['emergency_fund', 'current_amount'] : ['form_answers', k], 'amount');
}
liabilities.forEach((l, i) => {
  if (l.outstanding_amount === null) bad(`${l.type} · amount outstanding`, l._raw, ['liabilities', i, 'outstanding_amount'], 'amount');
  if (l.interest_rate === null) bad(`${l.type} · interest rate (% per year)`, l._raw, ['liabilities', i, 'interest_rate'], 'rate');
  if (l.emi === null) bad(`${l.type} · monthly EMI`, l._raw, ['liabilities', i, 'emi'], 'amount');
});
savings_investments.forEach((v, i) => {
  if (v.current_value === null) bad(`${v.type} · current value`, v._raw, ['savings_investments', i, 'current_value'], 'amount');
  if (v.monthly_contribution === null) bad(`${v.type} · monthly amount`, v._raw, ['savings_investments', i, 'monthly_contribution'], 'amount');
});
d.unreadable = unreadable;

return [{ json: computeDerived(d) }];

// Guardrail passed: carry the profile on unchanged (the Guardrails node outputs only its check result).
const d = $('Build Financial Profile').first().json;
return [{ json: { ...d, guardrail: { goal_text: 'passed' } } }];

// Guardrail failed: the typed text looked like an instruction to the AI or was off-topic.
// Keep the plan working but send only the structured choice (goal type) to the LLM prompts.
const d = JSON.parse(JSON.stringify($('Build Financial Profile').first().json));
const flagged = { goal_details: d.goal?.details || '', other_label: d.form_answers?.investments?.other_label || '' };
d.goal.details = '';
d.goal.description = d.goal.goal_type && d.goal.goal_type !== 'Other' ? d.goal.goal_type : 'Personal savings goal';
if (d.form_answers?.investments) d.form_answers.investments.other_label = '';
(d.savings_investments || []).forEach(v => { if (v._key === 'other') v.type = 'Other investment'; });
d.guardrail = { goal_text: 'neutralised', flagged_text: flagged, checks: $json.checks || [] };
return [{ json: d }];

// Chat input failed a guardrail - answer kindly instead of passing it to the agent.
const checks = JSON.stringify($json.checks || []).toLowerCase();
let output;
if (/pii|credit_card|pan|aadhaar|passport|iban|bank/.test(checks)) {
  output = "For your safety, please don't share card numbers, PAN, Aadhaar, passport or bank account details here - I never need them. " +
           'Ask me anything about your plan, and share your email if you want me to look up your saved profile.';
} else if (/secret/.test(checks)) {
  output = 'That looks like a password or secret key - please never paste those into a chat. How can I help with your finances?';
} else {
  output = "I can only help with personal finance - your goals, savings, loans, insurance, investments and your saved plan. " +
           'What would you like to know?';
}
return [{ json: { output, guardrail: 'refused' } }];

// Hosted chat page: it shows only text, so a proposed change is confirmed on the report page.
const j = $json;
let output = j.reply ?? j.output ?? '';
if (j.confirm && j.confirm.report_id) {
  let base = 'http://localhost:5678/';
  try { base = $env.WEBHOOK_URL || $env.N8N_WEBHOOK_URL || base; } catch (e) { /* env access blocked: keep the default */ }
  output += `\n\nTo apply it, open your plan and press Yes: ${base.replace(/\/$/, '')}/webhook/pfa/report?id=${j.confirm.report_id}&pending=${j.confirm.id}`;
}
return [{ json: { output } }];

// The deposit planner's answer for the fixed-income part of a Low-risk (or short-horizon) plan.
// A failure never blocks the report - the plan simply goes on without the deposit section.
const proj = $('Compute Future Projection').first().json;
const p = $json || {};
const fi = (proj.monthly_plan.rows || []).find(r => r.bucket === 'Fixed income') || {};
let deposit_plan;
if (!p.ok) {
  deposit_plan = { ok: false, reason: (p.errors || [p.error && (p.error.message || p.error)] || []).filter(Boolean).join('; ') || 'deposit planner unavailable' };
} else {
  const rd = p.recurring_deposit_plan || {};
  const best = rd.best;
  deposit_plan = {
    ok: true,
    monthly_amount: fi.amount || 0,
    goal_share: p.inputs.goal_amount_todays_money,
    goal_date: p.inputs.goal_date,
    rate_type: p.inputs.rate_type,
    reached: !!rd.reached,
    verdict: best ? (rd.reached ? 'covers the fixed-income share of your goal' : 'falls short of the fixed-income share') : p.verdict,
    steps: best ? best.steps.map(s => ({ bank: s.bank, tenor: s.tenor, term_months: s.term_months, times: s.times, rate_pct: s.rate_pct,
                                         start: s.start, end: s.end, value_at_end: s.value_at_end,
                                         rate_note: /RD rate list/.test(s.rate_source || '') ? 'RD rate' : 'FD card rate for this tenor' })) : [],
    cash_months: best ? best.cash_months : 0,
    cash_value: best ? Math.round((fi.amount || 0) * best.cash_months) : 0,
    total_paid: best ? best.total_paid : 0,
    value_on_goal_date: best ? best.value_on_goal_date : 0,
    installment_needed: best ? best.installment_needed_for_goal : null,
    alternatives: (rd.alternatives || []).map(a => ({ bank: a.bank, tenor: a.tenor, rate_pct: a.rate_pct, value: a.value_in_todays_money })),
    as_of: (p.notes || []).join(' ').match(/as of ([^)]+)\)/)?.[1] || '',
  };
}
// the monthly-plan row now says where the fixed-income money goes
const rows = (proj.monthly_plan.rows || []).map(r => r.bucket === 'Fixed income' && deposit_plan.ok && deposit_plan.steps.length
  ? { ...r, instrument: 'Bank RD: ' + deposit_plan.steps.map(s => `${s.bank} ${s.term_months}m @ ${s.rate_pct}%`).join(', then ') } : r);
return [{ json: { ...proj, monthly_plan: { ...proj.monthly_plan, rows }, deposit_plan } }];

// ---- shared helpers (inlined into each Code node by the builder) ----

// Accepts what people actually type: 85000, 85,000, "85K", "1.2L", "2.5 lakh", "3Cr",
// "Rs 12,00,000". Returns a number, or null if it cannot be understood - null is deliberate:
// `Check Profile Completeness` then asks the user instead of silently using 0.
function parseAmount(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  let s = String(v).toLowerCase().trim();
  if (!s) return null;
  s = s.replace(/[₹$€£¥,\s_]/g, '').replace(/^(rs\.?|inr|usd|eur|gbp|aed|sgd)/, '');
  const m = s.match(/^(-?\d+(?:\.\d+)?)(.*)$/);
  if (!m) return null;
  const n = parseFloat(m[1]);
  if (!Number.isFinite(n)) return null;
  const suffix = m[2].replace(/[^a-z]/g, '');
  const mult =
    suffix === ''                                              ? 1    :
    /^(c|cr|crs|crore|crores)$/.test(suffix)                   ? 1e7  :
    /^(l|lk|lac|lacs|lakh|lakhs)$/.test(suffix)                ? 1e5  :
    /^(k|th|thousand|thousands)$/.test(suffix)                 ? 1e3  :
    /^(m|mn|million|millions)$/.test(suffix)                   ? 1e6  :
    /^(b|bn|billion|billions)$/.test(suffix)                   ? 1e9  :
    /^(pa|pm|permonth|peryear|month|year|yr|mo)$/.test(suffix) ? 1    :
    null;
  return mult === null ? null : n * mult;
}

// Optional amount: blank means 0, anything typed but unreadable means null.
function parseOptional(v) {
  if (v === null || v === undefined || String(v).trim() === '') return 0;
  return parseAmount(v);
}

// Interest rates are never scaled - "8.5%", "8.5 % p.a." and "8.5" all mean 8.5.
function parseRate(v) {
  if (v === null || v === undefined || String(v).trim() === '') return null;
  const n = parseFloat(String(v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
}

const esc = s => String(s ?? '').replace(/[&<>"']/g, c =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const trim2 = x => String(Math.round(x * 100) / 100);

// Friendly short money for chat bubbles: ₹1.22L, ₹18L, ₹1.5Cr, $85K.
function fmtShort(n, cur) {
  const v = Number(n) || 0;
  const sign = v < 0 ? '-' : '';
  const a = Math.abs(v);
  if (!cur || cur === 'INR') {
    if (a >= 1e7) return sign + '₹' + trim2(a / 1e7) + 'Cr';
    if (a >= 1e5) return sign + '₹' + trim2(a / 1e5) + 'L';
    if (a >= 1e3) return sign + '₹' + trim2(a / 1e3) + 'K';
    return sign + '₹' + Math.round(a);
  }
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: cur,
      notation: 'compact', maximumFractionDigits: 1 }).format(v);
  } catch (e) { return cur + ' ' + Math.round(v); }
}

// Value to pre-fill an input with. Uses K/L/Cr shorthand only when it is exact,
// so re-submitting a pre-filled form never changes the stored number.
function shorthand(n, cur) {
  if (n === null || n === undefined || n === '') return '';
  const v = Number(n);
  if (!Number.isFinite(v)) return String(n);
  if (v === 0) return '0';
  if (!cur || cur === 'INR') {
    for (const [div, suf] of [[1e7, 'Cr'], [1e5, 'L'], [1e3, 'K']]) {
      if (Math.abs(v) >= div && Math.abs(Math.round((v / div) * 100) / 100 * div - v) < 0.5) return trim2(v / div) + suf;
    }
  }
  return String(Math.round(v * 100) / 100);
}

const firstName = full => String(full || '').trim().split(/\s+/)[0] || 'there';

const monthsUntil = (dateStr) => {
  const t = new Date(dateStr);
  if (!dateStr || isNaN(t.getTime())) return null;
  return Math.round((t - new Date()) / (1000 * 60 * 60 * 24 * 30.44));
};

const monthYear = (dateStr) => {
  const t = new Date(dateStr);
  return isNaN(t.getTime()) ? String(dateStr || '') :
    t.toLocaleDateString('en-GB', { month: 'short', year: 'numeric' });
};

// Rough annual CTC -> monthly in-hand for India, FY 2026-27 new tax regime.
// Assumptions (shown to the user, who confirms or corrects the figure):
// basic = 40% of CTC, employer + employee PF = 12% of basic each, gratuity = 4.81% of basic,
// standard deduction 75,000, section 87A rebate up to 12L taxable, 4% cess, professional tax 2,500.
function estimateInHand(ctc, cur) {
  const c = Number(ctc) || 0;
  if (c <= 0) return null;
  if (cur && cur !== 'INR') return Math.round((c * 0.72) / 12 / 100) * 100;  // generic rough cut
  const basic = c * 0.40;
  const employerPf = basic * 0.12, gratuity = basic * 0.0481, employeePf = basic * 0.12;
  const gross = c - employerPf - gratuity;
  const taxable = Math.max(0, gross - 75000);
  const slabs = [[400000, 0], [800000, 0.05], [1200000, 0.10], [1600000, 0.15],
                 [2000000, 0.20], [2400000, 0.25], [Infinity, 0.30]];
  let tax = 0, prev = 0;
  for (const [upto, rate] of slabs) {
    if (taxable > prev) tax += (Math.min(taxable, upto) - prev) * rate;
    prev = upto;
  }
  if (taxable <= 1200000) tax = 0;                                  // 87A rebate
  else tax = Math.min(tax, taxable - 1200000);                      // marginal relief
  const surcharge = taxable > 2e7 ? 0.25 : taxable > 1e7 ? 0.15 : taxable > 5e6 ? 0.10 : 0;
  tax = tax * (1 + surcharge) * 1.04;
  const net = gross - employeePf - tax - 2500;
  return Math.round(net / 12 / 500) * 500;
}

// Everything downstream reads `derived`; recompute it from the canonical profile.
function computeDerived(d) {
  const salary = Number(d.profile?.current_monthly_salary) || 0;
  const monthlyExpenses = Number(d.emergency_fund?.monthly_essential_expenses) || 0;
  const emergency = Number(d.emergency_fund?.current_amount) || 0;
  const totalEmi = (d.liabilities || []).reduce((s, l) => s + (Number(l.emi) || 0), 0);
  const totalDebt = (d.liabilities || []).reduce((s, l) => s + (Number(l.outstanding_amount) || 0), 0);
  const totalSavingsValue = (d.savings_investments || []).reduce((s, i) => s + (Number(i.current_value) || 0), 0);
  const monthlyContrib = (d.savings_investments || []).reduce((s, i) => s + (Number(i.monthly_contribution) || 0), 0);
  const surplus = salary - totalEmi - monthlyExpenses;
  d.emergency_fund = d.emergency_fund || {};
  d.emergency_fund.has_fund = emergency > 0;
  d.emergency_fund.months_of_expenses_covered = monthlyExpenses > 0
    ? Number((emergency / monthlyExpenses).toFixed(1)) : 0;
  d.derived = {
    totalEmi, totalDebt, totalSavingsValue, monthlyContrib,
    emergencyFund: emergency,
    netWorth: totalSavingsValue + emergency - totalDebt,
    surplus,
    freeCashAfterInvesting: surplus - monthlyContrib,
    savingsRatePct: salary > 0 ? Number(((surplus / salary) * 100).toFixed(1)) : null,
  };
  return d;
}

// The advisor's chat bubble at the top of every conversational page.
// n8n strips style/class attributes from form HTML, so the look comes from FORM_CSS.
const bubble = (heading, paragraphs) =>
  `<h3>${heading}</h3>` + paragraphs.filter(Boolean).map(p => `<p>${p}</p>`).join('');

const LOAN_TYPES = ['Home loan', 'Car loan', 'Personal loan', 'Education loan',
                    'Credit card dues', 'Gold loan', 'Other loan'];
const NO_LOANS = "None - I'm debt-free";
// Risk appetite: answered as a gut reaction to a fall, stored as Low / Medium / High.
const RISK_OPTIONS = {
  Low:    "Low - I'd sell to stop the loss. Keep my money safe, even if it grows slowly (FDs, PPF)",
  Medium: "Medium - I'd wait for it to recover. Some ups and downs are fine (mostly mutual funds)",
  High:   "High - I'd invest more while it's cheap. I'm fine with big swings (funds + stocks)",
};
const riskFromAnswer = a => (String(a || '').match(/^(Low|Medium|High)\b/) || [])[1] || null;
const slug = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');

// ---- v3.4 helpers (appended to the shared helpers by tools/build_v34.py) ----

const GOALS = ['Buy a home', 'Retirement', "Child's education", "Child's wedding", 'Buy a car',
               'Start a business', 'Travel or sabbatical', 'Build long-term wealth', 'Other'];
const CURRENCIES = ['INR', 'USD', 'EUR', 'GBP', 'AED', 'SGD'];
const INVESTMENT_KEYS = ['mf', 'stocks', 'gold', 'fd', 'pf', 'cash', 'other'];
const VERDICT_LABEL = { on_track: 'On track', small_gap: 'Slightly behind', large_gap: 'Significant gap' };

// A report id nobody can guess (it is the only key to a report page).
function newReportId() {
  const c = globalThis.crypto;
  if (c && typeof c.randomUUID === 'function') return c.randomUUID().replace(/-/g, '');
  let s = '';
  while (s.length < 32) s += Math.random().toString(16).slice(2);
  return s.slice(0, 32);
}

// The step form's answers (strings as typed) for a saved profile. v3.4 profiles keep the raw answers;
// older ones (v2 / v3 forms) are mapped back the same way the old "Evaluate Journey" node did.
function answersFromProfile(saved) {
  if (typeof saved === 'string') { try { saved = JSON.parse(saved); } catch (e) { saved = {}; } }
  saved = saved || {};
  if (saved.form_answers && saved.form_answers.raw) return JSON.parse(JSON.stringify(saved.form_answers.raw));
  const fa = saved.form_answers || {};
  const cur = saved.profile?.currency || 'INR';
  const pick = (...vals) => vals.find(v => v !== undefined && v !== null && v !== '') ?? '';
  const loanBucket = t => {
    t = String(t || '').toLowerCase();
    if (/home|house|housing|mortgage/.test(t)) return 'Home loan';
    if (/car|vehicle|auto|bike/.test(t)) return 'Car loan';
    if (/educat|student/.test(t)) return 'Education loan';
    if (/credit|card/.test(t)) return 'Credit card dues';
    if (/gold/.test(t)) return 'Gold loan';
    if (/personal/.test(t)) return 'Personal loan';
    return 'Other loan';
  };
  const invBucket = t => {
    t = String(t || '').toLowerCase();
    if (/mutual|\bmf\b|sip|elss|index|etf|fund/.test(t) && !/gold/.test(t)) return 'mf';
    if (/gold|sgb|silver/.test(t)) return 'gold';
    if (/stock|share|equity|demat/.test(t)) return 'stocks';
    if (/\bfd\b|\brd\b|fixed|recurring|deposit|bond/.test(t)) return 'fd';
    if (/ppf|epf|vpf|provident/.test(t)) return 'pf';
    if (/saving|cash|bank|liquid/.test(t)) return 'cash';
    return 'other';
  };
  let loans = fa.loans;
  if (!loans) {
    loans = {};
    (saved.liabilities || []).forEach(l => {
      const b = loanBucket(l.type);
      const o = loans[b] || { outstanding: 0, rate: 0, emi: 0, _w: 0 };
      const amt = Number(l.outstanding_amount) || 0;
      o.outstanding += amt; o.emi += Number(l.emi) || 0; o._w += amt * (Number(l.interest_rate) || 0);
      o.rate = o.outstanding > 0 ? Number((o._w / o.outstanding).toFixed(2)) : Number(l.interest_rate) || 0;
      loans[b] = o;
    });
  }
  let inv = fa.investments;
  if (!inv) {
    inv = {};
    (saved.savings_investments || []).forEach(s => {
      const b = invBucket(s.type);
      inv[b + '_value'] = (Number(inv[b + '_value']) || 0) + (Number(s.current_value) || 0);
      inv[b + '_monthly'] = (Number(inv[b + '_monthly']) || 0) + (Number(s.monthly_contribution) || 0);
      if (b === 'other' && !inv.other_label) inv.other_label = s.type;
    });
  }
  const insOf = re => (saved.insurance || []).filter(i => re.test(String(i.type || '').toLowerCase()));
  const sum = (arr, k) => arr.reduce((s, x) => s + (Number(x[k]) || 0), 0);
  const termIns = insOf(/term|life/), healthIns = insOf(/health|medic|mediclaim/);
  const desc = String(saved.goal?.description || '').toLowerCase();
  const goalType = saved.goal?.goal_type || (!desc ? '' : /house|home|flat|property/.test(desc) ? 'Buy a home'
    : /retire/.test(desc) ? 'Retirement' : /educat|college|school/.test(desc) ? "Child's education"
    : /wedding|marriage/.test(desc) ? "Child's wedding" : /car|vehicle/.test(desc) ? 'Buy a car'
    : /business|startup/.test(desc) ? 'Start a business' : /travel|sabbatical|trip/.test(desc) ? 'Travel or sabbatical'
    : /wealth|corpus|invest/.test(desc) ? 'Build long-term wealth' : 'Other');
  const sh = v => shorthand(v, cur);
  const loanAnswers = {};
  for (const [t, l] of Object.entries(loans)) loanAnswers[t] = { outstanding: sh(l.outstanding), rate: l.rate ? String(l.rate) : '', emi: sh(l.emi) };
  const invAnswers = { other_label: inv.other_label || '' };
  for (const k of INVESTMENT_KEYS) { invAnswers[`${k}_value`] = sh(inv[`${k}_value`]); invAnswers[`${k}_monthly`] = sh(inv[`${k}_monthly`]); }
  return {
    user_name: pick(saved.profile?.user_name), age: pick(saved.profile?.age), currency: cur,
    annual_ctc: sh(saved.profile?.annual_ctc), goal_type: goalType,
    goal_details: pick(saved.goal?.details, goalType === 'Other' ? saved.goal?.description : ''),
    target_amount: sh(saved.goal?.target_amount), target_date: pick(saved.goal?.target_date),
    take_home: sh(saved.profile?.current_monthly_salary), expenses: sh(saved.emergency_fund?.monthly_essential_expenses),
    emergency: sh(saved.emergency_fund?.current_amount),
    term_cover: sh(pick(fa.term_cover, termIns.length ? sum(termIns, 'sum_assured') : '')),
    term_premium: sh(pick(fa.term_premium, termIns.length ? sum(termIns, 'premium_annual') : '')),
    health_cover: sh(pick(fa.health_cover, healthIns.length ? sum(healthIns, 'sum_assured') : '')),
    health_premium: sh(pick(fa.health_premium, healthIns.length ? sum(healthIns, 'premium_annual') : '')),
    loan_types: saved.profile ? (Object.keys(loans).length ? Object.keys(loans) : [NO_LOANS]) : [],
    loans: loanAnswers, investments: invAnswers,
    risk: saved.profile?.risk_appetite || '',
  };
}

// A plan change asked for in the chat, applied to the step-form answers (port of the Python app's
// apply_changes). Returns { answers, log, ignored }; answers is null when nothing would change.
function applyPlanChanges(answers, changes) {
  const a = JSON.parse(JSON.stringify(answers || {}));
  const cur = a.currency || 'INR';
  const log = [], ignored = [];
  const amt = (label, v) => { const n = parseAmount(v); if (n === null || n < 0) { ignored.push(`${label} (could not read "${v}")`); return null; } return n; };
  const setAmount = (field, label, v, current) => {
    const n = amt(label, v); if (n === null) return;
    if (current !== null && current !== undefined && Math.abs(Number(current) - n) < 0.5) { ignored.push(`${label} is already ${fmtShort(n, cur)}`); return; }
    log.push(`${label} ${fmtShort(current || 0, cur)} → ${fmtShort(n, cur)}`);
    a[field] = shorthand(n, cur);
  };
  a.investments = a.investments || {};
  for (const [k, v] of Object.entries(changes || {})) {
    if (v === null || v === undefined || v === '') continue;
    if (k === 'monthly_sip_total') {
      const n = amt('monthly investing', v); if (n === null) continue;
      const inv = a.investments;
      const before = INVESTMENT_KEYS.reduce((s, key) => s + (parseOptional(inv[`${key}_monthly`]) || 0), 0);
      if (Math.abs(before - n) < 0.5) { ignored.push(`Monthly investing is already ${fmtShort(n, cur)}`); continue; }
      if (n > before) inv.mf_monthly = shorthand((parseOptional(inv.mf_monthly) || 0) + (n - before), cur);   // the extra goes to mutual funds
      else {
        const f = before ? n / before : 0;                                                                   // scale every SIP down
        for (const key of INVESTMENT_KEYS) { const m = parseOptional(inv[`${key}_monthly`]) || 0; if (m) inv[`${key}_monthly`] = shorthand(Math.round(m * f), cur); }
      }
      log.push(`Monthly investing ${fmtShort(before, cur)} → ${fmtShort(n, cur)}`);
    } else if (k === 'target_amount') {
      const n = amt('target', v); if (n !== null && n >= 10000) setAmount('target_amount', 'Target', n, parseAmount(a.target_amount));
    } else if (k === 'target_date') {
      const s = String(v).slice(0, 10), t = new Date(s);
      if (isNaN(t.getTime()) || t <= new Date()) ignored.push('target date (must be in the future)');
      else if (s === a.target_date) ignored.push(`Target date is already ${s}`);
      else { log.push(`Target date ${a.target_date || '-'} → ${s}`); a.target_date = s; }
    } else if (k === 'risk_appetite') {
      const m = String(v).match(/low|medium|high/i);
      const r = m ? m[0][0].toUpperCase() + m[0].slice(1).toLowerCase() : '';
      if (!['Low', 'Medium', 'High'].includes(r)) ignored.push('risk (Low, Medium or High)');
      else if (r === a.risk) ignored.push(`Risk is already ${r}`);
      else { log.push(`Risk ${a.risk || 'Medium'} → ${r}`); a.risk = r; }
    } else if (k === 'take_home') setAmount('take_home', 'In-hand pay', v, parseAmount(a.take_home));
    else if (k === 'annual_ctc') setAmount('annual_ctc', 'CTC', v, parseAmount(a.annual_ctc));
    else if (k === 'expenses') setAmount('expenses', 'Essentials', v, parseAmount(a.expenses));
    else if (k === 'emergency_fund') setAmount('emergency', 'Emergency fund', v, parseOptional(a.emergency));
    else if (k === 'emergency_lumpsum') {
      const n = amt('emergency deposit', v);
      if (n) { const before = parseOptional(a.emergency) || 0; log.push(`Emergency fund ${fmtShort(before, cur)} → ${fmtShort(before + n, cur)}`); a.emergency = shorthand(before + n, cur); }
    } else if (k === 'term_cover' || k === 'health_cover') setAmount(k, k === 'term_cover' ? 'Term cover' : 'Health cover', v, parseOptional(a[k]));
    else if (k === 'remove_loan') {
      const t = (a.loan_types || []).find(x => x.toLowerCase() === String(v).toLowerCase().trim());
      if (!t) ignored.push(`remove loan (no "${v}" on file)`);
      else {
        a.loan_types = a.loan_types.filter(x => x !== t);
        if (!a.loan_types.length) a.loan_types = [NO_LOANS];
        if (a.loans) delete a.loans[t];
        log.push(`Removed ${t}`);
      }
    } else ignored.push(k);
  }
  return { answers: log.length ? a : null, log, ignored };
}

